import argparse,json,decimal
from pathlib import Path
import numpy as np
from scipy.linalg import eigh_tridiagonal
from stable import StableFull
ap=argparse.ArgumentParser();ap.add_argument('--output',required=True);arg=ap.parse_args();m=StableFull();s=np.load('nonlinear_transfer_2026_10_25/run_equilibrium_stable/state.npz');a=s['a'];x=s['alpha'];chi=s['chi'];mt=sum(abs(a[0])**2);u=mt*m.tt**2;D=decimal.Decimal;decimal.getcontext().prec=80;truth=np.array([float(-(D(1)-D(str(v))).ln()-D(str(v))) for v in u]);stable=m.f(u)[0];naive=-np.log1p(-u)-u
rel=float(max(abs(stable-truth)/truth));assert rel<1e-13
d=.1*a*(np.sin(np.arange(m.n))+.3j*np.cos(np.arange(m.n)))[None,:];h=1e-4;mu=m.pot(a,x,True)[1];fd=(m.pot(a+h*d,x)-m.pot(a-h*d,x))/(2*h);exact=2*np.real(np.sum(mu*np.conj(a)*d));err=float(abs(fd-exact)/max(abs(fd),1e-20));assert err<1e-6
xp=x+.01*np.sin(np.arange(m.n));parts=m.vacuum_parts(a,chi);grad,hd,off,scale=m.carrier_force(xp,parts);direction=.1*np.cos(np.arange(m.n));h=1e-5;fdx=(m.energy(a,xp+h*direction,chi,s['pi'])-m.energy(a,xp-h*direction,chi,s['pi']))/(2*h);ex=float(grad@direction);ec=float(abs(fdx-ex)/max(abs(fdx),1e-20));assert ec<1e-6
g,Hd,Ho,_=m.carrier_force(x,m.vacuum_parts(a,chi));ev=float(eigh_tridiagonal(Hd/m.vol,Ho/np.sqrt(m.vol[:-1]*m.vol[1:]),select='i',select_range=(0,0),check_finite=False)[0][0]);ka=m.kd*a;ka[:,:-1]+=m.ko*a[:,1:];ka[:,1:]+=m.ko*a[:,:-1];ha=mu*a+ka+m.J*m.alignment(a,x,chi);mass=np.sum(abs(a)**2,axis=0);mum=np.real(np.sum(np.conj(a)*ha,axis=0))/mass;active=mass>1e-7;spread=float(max(abs(mum[active]-np.median(mum[active]))));out={'tail_W_stable_max_relative_error_vs_80digit':rel,'tail_W_naive_max_relative_error_vs_80digit':float(max(abs(naive-truth)/truth)),'stable_tail_energy':float(sum(m.tw*stable/m.tt**4)),'naive_tail_energy':float(sum(m.tw*naive/m.tt**4)),'high_conversion_density_force_relative_error':err,'nonstationary_carrier_force_relative_error':ec,'static_minimum_volume_normalized_carrier_H':ev,'active_density_chemical_spread':spread,'absolute_material_stationarity_residual':float(max(abs(ha-(np.real(np.sum(np.conj(a)*ha))/m.M)*a).ravel())),'scope':'One radial stable benchmark. Carrier Hessian is conditional on fixed material; it is not the coupled relaxed boundary Hessian.'};Path(arg.output).write_text(json.dumps(out,indent=2)+'\n');print(out,flush=True)
